when.condition:
@{
    try {
      if (!context.Variables.ContainsKey("gatewayQueryGuardDecision")) { return false; }
      var decision = JObject.Parse((string)context.Variables["gatewayQueryGuardDecision"]);
      return (new string[] { "liveCreate", "realtimeCreate", "piiMcp" }).Contains((string)decision["route"]);
    } catch { return false; }
  }

trace.message:
@{
      try {
        var decision = JObject.Parse((string)context.Variables["gatewayQueryGuardDecision"]);
        var route = (string)decision["route"];
        if (!(new string[] { "liveCreate", "realtimeCreate", "piiMcp" }).Contains(route)) { route = "unknown"; }
        var method = (string)decision["httpMethod"];
        if (!(new string[] { "POST", "GET", "DELETE" }).Contains(method)) { method = "unknown"; }
        var mode = (string)decision["mode"];
        if (mode != "observe" && mode != "reject") { mode = "unknown"; }
        var phase = context.Variables.ContainsKey("gatewayQueryPhase") ? (string)context.Variables["gatewayQueryPhase"] : "unknown";
        if (!(new string[] { "received", "query-rejected", "guard-error", "backend-response", "policy-error" }).Contains(phase)) { phase = "unknown"; }
        var presence = (string)decision["presence"];
        if (presence != "none" && presence != "present") { presence = "unknown"; }
        var count = (string)decision["countBucket"];
        if (!(new string[] { "0", "1", "2-4", "5+" }).Contains(count)) { count = "unknown"; }
        var duplicate = (string)decision["duplicates"];
        if (duplicate != "yes" && duplicate != "no") { duplicate = "unknown"; }
        var status = phase == "query-rejected" ? 400 : phase == "guard-error" ? 503
          : phase == "backend-response" || phase == "policy-error" ? (context.Variables.ContainsKey("gatewayAuditStatus") ? (int)context.Variables["gatewayAuditStatus"] : 0) : 0;
        var statusClass = status >= 200 && status < 300 ? "2xx" : status >= 300 && status < 400 ? "3xx"
          : status >= 400 && status < 500 ? "4xx" : status >= 500 && status < 600 ? "5xx" : "unknown";
        return new JObject(new JProperty("schemaVersion", 1), new JProperty("event", "query-guard"),
          new JProperty("route", route), new JProperty("httpMethod", method), new JProperty("mode", mode),
          new JProperty("phase", phase), new JProperty("presence", presence), new JProperty("countBucket", count),
          new JProperty("duplicates", duplicate), new JProperty("statusClass", statusClass)).ToString(Newtonsoft.Json.Formatting.None);
      } catch {
        return "{\"schemaVersion\":1,\"event\":\"query-guard\",\"route\":\"unknown\",\"httpMethod\":\"unknown\",\"mode\":\"unknown\",\"phase\":\"unknown\",\"presence\":\"unknown\",\"countBucket\":\"unknown\",\"duplicates\":\"unknown\",\"statusClass\":\"unknown\"}";
      }
    }
